using System.Collections;
using System.IO;
using UnityEditor;
using UnityEngine;
using UnityEngine.UI;
using UnityEngine.EventSystems;
using System.Collections.Generic;
[InitializeOnLoad] public static class StorybookDebugEntryValidation{
 const string Out="output/debug-entry/";static bool running;static double started;
 static StorybookDebugEntryValidation(){EditorApplication.update+=Tick;EditorApplication.playModeStateChanged+=s=>{if(s==PlayModeStateChange.EnteredEditMode&&SessionState.GetBool("DEBUG_ENTRY_QA",false)){SessionState.SetBool("DEBUG_ENTRY_QA",false);SessionState.SetBool("MONSTER_QA_DISABLE_SAVE",false);running=false;}};}
 static void Tick(){if(EditorApplication.isCompiling||EditorApplication.isUpdating)return;if(!EditorApplication.isPlayingOrWillChangePlaymode&&File.Exists(Out+"validate.request")){File.Delete(Out+"validate.request");File.WriteAllText(Out+"validation.txt","");UnityEditor.SceneManagement.EditorSceneManager.OpenScene("Assets/Scenes/MainScenes/Gameplay.unity");SessionState.SetBool("DEBUG_ENTRY_QA",true);SessionState.SetBool("MONSTER_QA_DISABLE_SAVE",true);EditorApplication.isPlaying=true;}if(EditorApplication.isPlaying&&SessionState.GetBool("DEBUG_ENTRY_QA",false)&&!running&&GameManager.single&&GameplayCanvas.single){running=true;started=EditorApplication.timeSinceStartup;GameManager.single.StartCoroutine(Run());}if(running&&EditorApplication.timeSinceStartup-started>180){Check(false,"timeout");EditorApplication.isPlaying=false;}}
 static void Check(bool ok,string s)=>File.AppendAllText(Out+"validation.txt",(ok?"PASS ":"FAIL ")+s+"\n");
 static IEnumerator Run(){var intro=Object.FindAnyObjectByType<CursedBookIntro>(FindObjectsInactive.Include);while(intro&&intro.gameObject.activeSelf)yield return null;yield return new WaitForSecondsRealtime(1);var gc=GameplayCanvas.single;gc.CancelInvoke("TryShowingXpBoosterNotification");gc.xpBoosterNotification.SetActive(false);gc.dailyCherriesPop.SetActive(false);TutorialManager.single.automatic=false;TutorialManager.single.view.Hide();var ui=gc.homeUI.settingsUI;
 foreach(var size in new[]{new Vector2Int(1080,1920),new Vector2Int(768,1024),new Vector2Int(720,1440)}){StorybookEquipmentValidation.Resolution(size.x,size.y);gc.homeUI.settingsButton.onClick.Invoke();yield return new WaitForSecondsRealtime(.3f);ui.scroll.verticalNormalizedPosition=0;yield return new WaitForSecondsRealtime(.3f);Check(ui.developer&&ui.IsOpen,"Persistent settings entry "+size);var rt=(RectTransform)ui.developer.transform;var hits=new List<RaycastResult>();EventSystem.current.RaycastAll(new PointerEventData(EventSystem.current){position=RectTransformUtility.WorldToScreenPoint(null,rt.TransformPoint(rt.rect.center))},hits);Check(hits.Count>0&&hits[0].gameObject.GetComponentInParent<Button>()==ui.developer,"Entry reachable "+size);yield return new WaitForEndOfFrame();var t=ScreenCapture.CaptureScreenshotAsTexture();File.WriteAllBytes(Out+"settings-"+size.x+"x"+size.y+".png",t.EncodeToPNG());Object.Destroy(t);ui.developer.onClick.Invoke();Check(DebugMenu.Instance.m_ShowDebug&&!ui.IsOpen&&!ui.group.blocksRaycasts,"Open debug releases settings input "+size);DebugMenu.Instance.Close();Check(!DebugMenu.Instance.m_ShowDebug&&!ui.IsOpen,"Close returns to game "+size);ui.Close();}
 StorybookEquipmentValidation.Resolution(1080,1920);File.AppendAllText(Out+"validation.txt","DONE\n");EditorApplication.isPlaying=false;}
}
